import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestOrdenar(unittest.TestCase):
    def test_ordem_crescente_devolve_a_lista_em_ordem(self):
        """ordem_crescente devolve a lista em ordem crescente"""
        self.assertEqual(rodar()["ordem_crescente"]([3, 1, 2]), [1, 2, 3])

    def test_ordem_crescente_muda_a_lista_original(self):
        """ordem_crescente muda a lista original no lugar"""
        numeros = [3, 1, 2]
        rodar()["ordem_crescente"](numeros)
        self.assertEqual(numeros, [1, 2, 3])

    def test_em_ordem_nao_muda_a_lista_original(self):
        """em_ordem devolve outra lista e nao muda a original"""
        numeros = [3, 1, 2]
        self.assertEqual(rodar()["em_ordem"](numeros), [1, 2, 3])
        self.assertEqual(numeros, [3, 1, 2])

    def test_o_segundo_melhor_pega_o_penultimo_da_ordem(self):
        """o_segundo_melhor devolve o segundo maior numero da lista"""
        self.assertEqual(rodar()["o_segundo_melhor"]([3, 9, 1]), 3)
        self.assertEqual(rodar()["o_segundo_melhor"]([4, 8, 6, 9]), 8)

